    title: 'Coffee Under the Paris Awning',
    subtitle: 'A sudden thunderstorm forced them into the same doorway. Neither wanted the rain to stop.',
    date: '2026-10-02',
    readTime: '5 min read',
    coverImage: 'https://images.unsplash.com/photo-1502602898657-3e91760cbb34?w=1200&q=85',
